// Level sizes for validation
const DESAFIO_LEVEL_SIZES: Record<number, Record<number, number>> = {
  1: { 1: 50, 2: 100, 3: 150, 4: 200, 5: 250 },
  2: { 1: 50, 2: 100, 3: 150, 4: 200, 5: 250 },
  3: { 1: 50, 2: 100, 3: 150, 4: 200, 5: 100 },
};
const QUIZ_LEVEL_SIZES: Record<string, number> = { principiante: 700, intermedio: 700, avanzado: 200, platino: 500 };
const VALID_QUIZ_LEVELS = ['principiante', 'intermedio', 'avanzado', 'platino'];

// ─── HANDLERS ───────────────────────────────────────────────────────────────

function handleDesafio(params: Record<string, unknown>): Response {
  const { corrida, nivel, questionIndex, selectedAnswer } = params;

  // Input validation
  if (typeof corrida !== 'number' || corrida < 1 || corrida > 5 || !Number.isInteger(corrida)) {
    return jsonResponse({ error: 'Invalid corrida (must be integer 1-5)' }, 400);
  }
  if (typeof nivel !== 'number' || nivel < 1 || nivel > 5 || !Number.isInteger(nivel)) {
    return jsonResponse({ error: 'Invalid nivel (must be integer 1-5)' }, 400);
  }
  if (typeof questionIndex !== 'number' || questionIndex < 0 || !Number.isInteger(questionIndex)) {
    return jsonResponse({ error: 'Invalid questionIndex (must be non-negative integer)' }, 400);
  }
  if (typeof selectedAnswer !== 'number' || !Number.isInteger(selectedAnswer) || (selectedAnswer !== -1 && (selectedAnswer < 0 || selectedAnswer > 3))) {
    return jsonResponse({ error: 'Invalid selectedAnswer (must be integer 0-3, or -1 for timeout)' }, 400);
  }

  // Corridas 1-3 are populated; 4-5 reserved for future question banks
  if (corrida > 3) {
    return jsonResponse({ error: 'Corrida ' + corrida + ' not available yet' }, 400);
  }

  const maxIndex = DESAFIO_LEVEL_SIZES[corrida]?.[nivel];
  if (!maxIndex || questionIndex >= maxIndex) {
    return jsonResponse({ error: 'questionIndex out of range for c' + corrida + 'n' + nivel + ' (max: ' + ((maxIndex || 0) - 1) + ')' }, 400);
  }

  const key = 'c' + corrida + '_n' + nivel + '_' + questionIndex;
  const correctIndex = DESAFIO_ANSWERS[key];

  if (correctIndex === undefined) {
    return jsonResponse({ error: 'Question not found' }, 404);
  }

  return jsonResponse({
    isCorrect: selectedAnswer === correctIndex,
    correctIndex,
  });
}

function handleQuiz(params: Record<string, unknown>): Response {
  const { level, questionIndex, selectedAnswer } = params;

  // Input validation
  if (typeof level !== 'string' || !VALID_QUIZ_LEVELS.includes(level)) {
    return jsonResponse({ error: 'Invalid level (must be one of: ' + VALID_QUIZ_LEVELS.join(', ') + ')' }, 400);
  }
  if (typeof questionIndex !== 'number' || questionIndex < 0 || !Number.isInteger(questionIndex)) {
    return jsonResponse({ error: 'Invalid questionIndex (must be non-negative integer)' }, 400);
  }
  if (typeof selectedAnswer !== 'number' || !Number.isInteger(selectedAnswer) || (selectedAnswer !== -1 && (selectedAnswer < 0 || selectedAnswer > 3))) {
    return jsonResponse({ error: 'Invalid selectedAnswer (must be integer 0-3, or -1 for timeout)' }, 400);
  }

  const maxIndex = QUIZ_LEVEL_SIZES[level];
  if (!maxIndex || questionIndex >= maxIndex) {
    return jsonResponse({ error: 'questionIndex out of range for level ' + level + ' (max: ' + ((maxIndex || 0) - 1) + ')' }, 400);
  }

  const key = level + '_' + questionIndex;
  const correctIndex = QUIZ_ANSWERS[key];

  if (correctIndex === undefined) {
    return jsonResponse({ error: 'Question not found' }, 404);
  }

  return jsonResponse({
    isCorrect: selectedAnswer === correctIndex,
    correctIndex,
  });
}

async function handleAcvolt(params: Record<string, unknown>): Promise<Response> {
  const { questionId, answerId } = params;

  // Input validation
  if (typeof questionId !== 'number' || questionId < 1 || !Number.isInteger(questionId)) {
    return jsonResponse({ error: 'Invalid questionId (must be positive integer)' }, 400);
  }
  if (typeof answerId !== 'number' || answerId < 1 || !Number.isInteger(answerId)) {
    return jsonResponse({ error: 'Invalid answerId (must be positive integer)' }, 400);
  }

  const SB_URL = Deno.env.get('SUPABASE_URL') || '';
  const SB_SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';

  if (!SB_URL || !SB_SERVICE_KEY) {
    console.error('[verify-answer] Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY');
    return jsonResponse({ error: 'Server configuration error' }, 500);
  }

  const supabase = createClient(SB_URL, SB_SERVICE_KEY);

  const { data, error } = await supabase
    .from('acvolt_answers')
    .select('is_correct')
    .eq('id', answerId)
    .eq('question_id', questionId)
    .single();

  if (error || !data) {
    return jsonResponse({ error: 'Answer not found' }, 404);
  }

  return jsonResponse({
    isCorrect: data.is_correct === true,
  });
}

async function handleExam(params: Record<string, unknown>): Promise<Response> {
  const { examId, questionIndex, selectedAnswer } = params;

  // Input validation
  if (typeof examId !== 'string' || examId.length < 10) {
    return jsonResponse({ error: 'Invalid examId (must be a valid UUID string)' }, 400);
  }
  if (typeof questionIndex !== 'number' || questionIndex < 0 || !Number.isInteger(questionIndex)) {
    return jsonResponse({ error: 'Invalid questionIndex (must be non-negative integer)' }, 400);
  }
  if (typeof selectedAnswer !== 'number' || !Number.isInteger(selectedAnswer) || (selectedAnswer !== -1 && (selectedAnswer < 0 || selectedAnswer > 3))) {
    return jsonResponse({ error: 'Invalid selectedAnswer (must be integer 0-3, or -1 for timeout)' }, 400);
  }

  const SB_URL = Deno.env.get('SUPABASE_URL') || '';
  const SB_SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';

  if (!SB_URL || !SB_SERVICE_KEY) {
    console.error('[verify-answer] Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY');
    return jsonResponse({ error: 'Server configuration error' }, 500);
  }

  const supabase = createClient(SB_URL, SB_SERVICE_KEY);

  const { data, error } = await supabase
    .from('zm_exams')
    .select('questions')
    .eq('id', examId)
    .single();

  if (error || !data) {
    return jsonResponse({ error: 'Exam not found' }, 404);
  }

  const examQuestions = data.questions;
  if (!Array.isArray(examQuestions) || questionIndex >= examQuestions.length) {
    return jsonResponse({ error: 'questionIndex out of range (max: ' + ((Array.isArray(examQuestions) ? examQuestions.length : 0) - 1) + ')' }, 400);
  }

  const question = examQuestions[questionIndex];
  if (!question || typeof question.correct !== 'number') {
    return jsonResponse({ error: 'Question data malformed' }, 500);
  }

  // Exam mode: only return isCorrect, never expose correctIndex
  // Prevents enumeration of answers via network inspection
  return jsonResponse({
    isCorrect: selectedAnswer === question.correct,
  });
}

// ─── MAIN HANDLER ───────────────────────────────────────────────────────────

Deno.serve(async (req) => {
  initCors(req);

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return jsonResponse({ error: 'Method not allowed. Use POST.' }, 405);
  }

  // Rate limit: 60 requests per 60 seconds per IP (1/sec average)
  const rl = await checkRateLimit(req, { maxRequests: 60, windowSeconds: 60 });
  if (!rl.allowed) return rateLimitResponse(corsHeaders);

  try {
    const body = await req.json();
    const { system, ...params } = body;

    if (typeof system !== 'string') {
      return jsonResponse({ error: 'Missing or invalid "system" field (must be: desafio, quiz, acvolt, exam)' }, 400);
    }

    switch (system) {
      case 'desafio':
        return handleDesafio(params);
      case 'quiz':
        return handleQuiz(params);
      case 'acvolt':
        return await handleAcvolt(params);
      case 'exam':
        return await handleExam(params);
      default:
        return jsonResponse({ error: 'Unknown system: ' + system + '. Must be: desafio, quiz, acvolt, exam' }, 400);
    }
  } catch (e) {
    console.error('[verify-answer] Unhandled error:', e);
    if (e instanceof SyntaxError) {
      return jsonResponse({ error: 'Invalid JSON body' }, 400);
    }
    return jsonResponse({ error: 'Internal server error' }, 500);
  }
});
